mapper.select:
select

from deploy_log

    deleted = 0
     and id= #{id}
     and deploy_id= #{deployId}
     and action= #{action}
     and operator like concat('%', #{operator}, '%')

order by id desc

select id, deploy_id, detail, seq
from deploy_log
where deleted = 0 and deploy_id = #{deployId} and log_type = 'EXEC' and seq > #{cursor}
order by seq asc
limit #{limit}
